INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(1550, 'copious', '/ˈkəʊpiəs/', 'adjective', '{"zh-TW":["豐富的；大量的"],"en":["abundant in supply; producing something in large quantities"]}', NULL, 'copious notes / copious evidence / copious rainfall', '[{"en":"She took copious notes during every lecture to review later.","zh-TW":"她在每次課堂上記錄了大量筆記，以便稍後複習。"},{"en":"Copious evidence was presented to support the defense''s case.","zh-TW":"呈交了大量證據來支持辯方的案件。"}]', '{"adverb":"copiously","noun":"copiousness"}', NULL, 3, 1550, NULL),
(1551, 'copy', '/ˈkɒpi/', 'noun', '{"zh-TW":["副本；複製"],"en":["a thing made to be the same as another"]}', NULL, 'make a copy / carbon copy', '[{"en":"Can you make a copy of this?","zh-TW":"你能複印一份嗎？"},{"en":"Keep a copy for your records.","zh-TW":"保留一份副本作為記錄。"}]', '{"verb":"copy"}', NULL, 1, 1551, 312),
(1552, 'copy machine', '/ˈkɒpi məˈʃiːn/', 'noun', '{"zh-TW":["影印機"],"en":["a device used to make copies of documents"]}', NULL, 'use the copy machine / copy machine maintenance', '[{"en":"The copy machine was out of paper during the meeting.","zh-TW":"會議期間影印機沒有紙了。"},{"en":"Please clear any paper jams in the copy machine.","zh-TW":"請清除影印機中的任何卡紙。"}]', NULL, NULL, 4, 1552, NULL),
(1553, 'copyright', '/ˈkɒpiraɪt/', 'noun', '{"zh-TW":["著作權；版權"],"en":["the legal right to control creative work"]}', NULL, 'copyright law / copyright infringement', '[{"en":"The book is protected by copyright.","zh-TW":"這本書受著作權保護。"},{"en":"Copyright infringement is illegal.","zh-TW":"侵犯版權是違法的。"}]', NULL, NULL, 3, 1553, NULL),
(1554, 'copyright infringement', '/ˈkɒpiraɪt ɪnˈfrɪndʒmənt/', 'noun', '{"zh-TW":["侵犯版權"],"en":["the unauthorized use of copyrighted material"]}', NULL, 'commit copyright infringement / avoid copyright infringement / copyright infringement claim', '[{"en":"Sharing copyrighted music without permission constitutes copyright infringement.","zh-TW":"未經許可分享受版權保護的音樂構成侵犯版權。"},{"en":"The publisher filed a copyright infringement suit against the website.","zh-TW":"出版商對該網站提起了侵犯版權訴訟。"}]', '{"verb":"infringe copyright"}', NULL, 5, 1554, NULL),
(1555, 'copywriting', '/ˈkɒpiˌraɪtɪŋ/', 'noun', '{"zh-TW":["文案寫作"],"en":["the activity of writing promotional text for advertising"]}', NULL, 'persuasive copywriting / website copywriting / email copywriting', '[{"en":"Effective copywriting highlights the benefits rather than features.","zh-TW":"有效的文案寫作強調利益而非功能特點。"},{"en":"She specialized in SEO copywriting for e-commerce websites.","zh-TW":"她專精於電子商務網站的SEO文案寫作。"}]', '{"verb":"copywrite","noun":"copywriter"}', NULL, 4, 1555, NULL),
(1556, 'coral bleaching', '/ˈkɒrəl ˈbliːtʃɪŋ/', 'noun', '{"zh-TW":["珊瑚白化"],"en":["the whitening of coral caused by heat stress that expels symbiotic algae"]}', NULL, 'coral bleaching event / mass coral bleaching / coral bleaching crisis', '[{"en":"Rising ocean temperatures triggered a mass coral bleaching event.","zh-TW":"海洋溫度上升引發了大規模珊瑚白化事件。"},{"en":"Coral bleaching threatens biodiversity in marine ecosystems worldwide.","zh-TW":"珊瑚白化威脅著全球海洋生態系統的生物多樣性。"}]', '{"verb":"bleach"}', NULL, 5, 1556, NULL),
(1557, 'core business', '/kɔːr ˈbɪznɪs/', 'noun', '{"zh-TW":["核心業務"],"en":["the main commercial activity that generates the majority of a company''s revenue"]}', NULL, 'focus on core business / non-core business', '[{"en":"The company divested non-core assets to focus on its core business.","zh-TW":"公司剝離了非核心資產以專注於其核心業務。"},{"en":"Strengthening core business operations is the priority for this fiscal year.","zh-TW":"加強核心業務運作是本財年的優先事項。"}]', NULL, NULL, 5, 1557, NULL),
(1558, 'core competency', '/kɔːr kɒmˈpiːtənsi/', 'noun', '{"zh-TW":["核心競爭力"],"en":["a unique capability that provides a competitive edge"]}', NULL, 'identify core competencies / build on core competencies', '[{"en":"Customer service is one of our core competencies.","zh-TW":"客戶服務是我們的核心競爭力之一。"},{"en":"The company focused on its core competencies and outsourced the rest.","zh-TW":"公司專注於核心競爭力，將其餘業務外包。"}]', '{"plural":"core competencies"}', NULL, 5, 1558, NULL),
(1559, 'core curriculum', '/kɔːr kəˈrɪkjʊləm/', 'noun', '{"zh-TW":["核心課程"],"en":["the essential subjects required of all students"]}', NULL, 'complete the core curriculum / core curriculum subjects', '[{"en":"Students must complete the core curriculum before choosing electives.","zh-TW":"學生必須完成核心課程後才能選擇選修課。"},{"en":"The core curriculum includes math, science, and language arts.","zh-TW":"核心課程包括數學、科學和語言藝術。"}]', NULL, NULL, 5, 1559, NULL),
(1560, 'core values', '/kɔːr ˈvæljuːz/', 'noun', '{"zh-TW":["核心價值觀"],"en":["the fundamental principles guiding an organization"]}', NULL, 'define core values / uphold core values', '[{"en":"The company''s core values include integrity and innovation.","zh-TW":"公司的核心價值觀包括誠信和創新。"},{"en":"Employees are expected to reflect the organization''s core values.","zh-TW":"員工應體現組織的核心價值觀。"}]', NULL, NULL, 4, 1560, NULL),
(1561, 'corkage', '/ˈkɔːrkɪdʒ/', 'noun', '{"zh-TW":["開瓶費"],"en":["a charge made for bringing your own bottle of wine to a restaurant"]}', NULL, 'corkage fee / corkage policy', '[{"en":"The restaurant charges a ten-dollar corkage fee per bottle.","zh-TW":"餐廳每瓶收取十元的開瓶費。"},{"en":"Ask about the corkage fee before bringing your own wine.","zh-TW":"自帶葡萄酒前請詢問開瓶費。"}]', NULL, NULL, 3, 1561, NULL),
(1562, 'corner', '/ˈkɔːrnər/', 'noun', '{"zh-TW":["角落；轉角","角落；拐角"],"en":["a point where two lines or surfaces meet","a place near where two roads meet","the point where two lines or walls meet"]}', NULL, 'around the corner / cut corners', '[{"en":"The coffee shop is around the corner.","zh-TW":"咖啡店就在轉角。"},{"en":"We cannot cut corners on safety.","zh-TW":"我們不能在安全方面偷工減料。"},{"en":"There''s a shop on the corner.","zh-TW":"拐角處有一家商店。"},{"en":"Success is just around the corner.","zh-TW":"成功就在眼前。"}]', '{"noun":"corner","verb":"corner"}', NULL, 2, 1562, NULL),
(1563, 'corollary', '/kəˈrɒləri/', 'noun', '{"zh-TW":["必然結果；推論"],"en":["a direct result or consequence; a proposition following from another"]}', NULL, 'logical corollary / natural corollary / direct corollary', '[{"en":"An inevitable corollary of higher wages is increased production costs.","zh-TW":"工資提高的必然結果是生產成本增加。"},{"en":"The study''s corollary suggests that more resources are needed.","zh-TW":"研究的推論表明需要更多資源。"}]', NULL, NULL, 3, 1563, NULL),
(1564, 'corporal', '/ˈkɔːrpərəl/', 'adjective', '{"zh-TW":["身體的；肉體的"],"en":["relating to the human body; physical punishment"]}', NULL, 'corporal punishment / corporal injury / corporal needs', '[{"en":"Corporal punishment in schools is prohibited in many countries.","zh-TW":"在許多國家，學校中的體罰是被禁止的。"},{"en":"The law distinguishes between corporal injury and emotional harm.","zh-TW":"法律區分身體傷害和精神傷害。"}]', NULL, NULL, 3, 1564, NULL),
(1565, 'corporate', '/ˈkɔːrpərət/', 'adjective', '{"zh-TW":["企業的；公司的","公司的；企業的"],"en":["relating to a large company or group"]}', '{"root":{"text":"corpor","meaning":"body (身體)"},"suffix":{"text":"-ate","meaning":"having (具有)"},"logic":"具有團體身體（法人）的，即「企業的」。"}', 'corporate culture / corporate governance / corporate strategy; corporate culture / corporate responsibility', '[{"en":"The corporate headquarters is located in New York.","zh-TW":"公司總部位於紐約。"},{"en":"Strong corporate governance builds investor trust.","zh-TW":"良好的公司治理建立投資者信任。"},{"en":"The corporate headquarters is in New York.","zh-TW":"公司總部在紐約。"},{"en":"Corporate responsibility is increasingly important.","zh-TW":"企業責任越來越重要。"}]', '{"noun":"corporation"}', NULL, 3, 1565, NULL),
(1566, 'corporate bond', '/ˈkɔːrpərɪt bɒnd/', 'noun', '{"zh-TW":["公司債券"],"en":["a debt security issued by a corporation to raise capital"]}', NULL, 'issue corporate bonds / invest in corporate bonds', '[{"en":"The company issued corporate bonds at a yield of 3.5%.","zh-TW":"公司以3.5%的收益率發行了公司債券。"},{"en":"Corporate bonds offer higher yields than government bonds.","zh-TW":"公司債券比政府債券提供更高的收益率。"}]', NULL, NULL, 5, 1566, NULL),
(1567, 'corporate communications', '/ˈkɔːrpərɪt kəˌmjuːnɪˈkeɪʃənz/', 'noun', '{"zh-TW":["企業傳播；企業溝通"],"en":["the management of a company internal and external communications"]}', NULL, 'oversee corporate communications / corporate communications team', '[{"en":"The corporate communications team drafted the press release.","zh-TW":"企業傳播團隊起草了新聞稿。"},{"en":"Effective corporate communications builds reputation and trust.","zh-TW":"有效的企業傳播建立了聲譽和信任。"}]', NULL, NULL, 5, 1567, NULL),
(1568, 'corporate culture', '/ˈkɔːrpərɪt ˈkʌltʃər/', 'noun', '{"zh-TW":["企業文化"],"en":["the values, practices, and beliefs shared by a company''s employees"]}', NULL, 'strong corporate culture / shape corporate culture', '[{"en":"A positive corporate culture attracts and retains talent.","zh-TW":"積極的企業文化吸引並留住人才。"},{"en":"The merger resulted in a clash of corporate cultures.","zh-TW":"合併導致了企業文化的衝突。"}]', NULL, NULL, 5, 1568, NULL),
(1569, 'corporate ethics', '/ˈkɔːrpərɪt ˈeθɪks/', 'noun', '{"zh-TW":["企業倫理；商業道德"],"en":["moral principles and standards guiding company behavior"]}', NULL, 'uphold corporate ethics / breach of corporate ethics', '[{"en":"The company''s corporate ethics policy prohibits conflicts of interest.","zh-TW":"公司的企業倫理政策禁止利益衝突。"},{"en":"Corporate ethics training is mandatory for all employees.","zh-TW":"企業倫理培訓對所有員工是強制性的。"}]', NULL, NULL, 5, 1569, NULL),
(1570, 'corporate governance', '/ˈkɔːrpərɪt ˈɡʌvərnəns/', 'noun', '{"zh-TW":["企業管治；公司治理"],"en":["the system by which companies are directed and controlled"]}', NULL, 'strong corporate governance / corporate governance policy', '[{"en":"Good corporate governance builds investor trust.","zh-TW":"良好的企業管治建立了投資者信任。"},{"en":"The board is responsible for upholding corporate governance standards.","zh-TW":"董事會負責維護公司治理標準。"}]', NULL, NULL, 5, 1570, NULL),
(1571, 'corporate headquarters', '/ˈkɔːrpərɪt ˈhedkwɔːrtərz/', 'noun', '{"zh-TW":["企業總部"],"en":["the main office where a company is managed and strategic decisions are made"]}', NULL, 'locate corporate headquarters / visit corporate headquarters', '[{"en":"The corporate headquarters was relocated to reduce operating costs.","zh-TW":"企業總部遷移以降低運營成本。"},{"en":"All major decisions are made at the corporate headquarters.","zh-TW":"所有重大決策都在企業總部做出。"}]', NULL, NULL, 5, 1571, NULL),
(1572, 'corporate income tax', '/ˈkɔːrpərɪt ˈɪnkʌm tæks/', 'noun', '{"zh-TW":["企業所得稅"],"en":["a tax imposed on a company profits by the government"]}', NULL, 'pay corporate income tax / corporate income tax rate', '[{"en":"The corporate income tax rate was reduced to attract investment.","zh-TW":"企業所得稅率降低以吸引投資。"},{"en":"Companies must file corporate income tax returns annually.","zh-TW":"公司必須每年申報企業所得稅。"}]', NULL, NULL, 5, 1572, NULL),
(1573, 'corporate loan', '/ˈkɔːrpərɪt loʊn/', 'noun', '{"zh-TW":["企業貸款；公司貸款"],"en":["a loan made by a bank to a business entity"]}', NULL, 'secure a corporate loan / corporate loan facility', '[{"en":"The company secured a 20 million corporate loan to fund its expansion.","zh-TW":"公司獲得了2000萬元的企業貸款為其擴張提供資金。"},{"en":"Corporate loans typically carry lower interest rates than personal loans.","zh-TW":"企業貸款通常比個人貸款利率更低。"}]', NULL, NULL, 5, 1573, NULL),
(1574, 'corporate restructuring', '/ˈkɔːrpərət ˈriːstrʌktʃərɪŋ/', 'noun', '{"zh-TW":["企業重組"],"en":["a significant modification of a company''s structure, operations, or finances"]}', NULL, 'undertake corporate restructuring / corporate restructuring plan', '[{"en":"The corporate restructuring eliminated 500 positions and closed 3 divisions.","zh-TW":"企業重組消除了500個職位並關閉了3個部門。"},{"en":"Corporate restructuring aims to improve efficiency and long-term profitability.","zh-TW":"企業重組旨在提高效率和長期盈利能力。"}]', '{"verb":"restructure"}', NULL, 5, 1574, NULL),
(1575, 'corporate social responsibility', '/ˈkɔːrpərət ˈsoʊʃəl rɪˌspɒnsɪˈbɪlɪti/', 'noun', '{"zh-TW":["企業社會責任"],"en":["a company''s commitment to ethical, social, and environmental goals"]}', NULL, 'corporate social responsibility report / CSR initiative / CSR policy', '[{"en":"The company''s CSR program funds education in local communities.","zh-TW":"公司的企業社會責任計劃資助當地社區的教育。"},{"en":"Investors increasingly consider corporate social responsibility in their decisions.","zh-TW":"投資者越來越多地在決策中考量企業社會責任。"}]', '{"abbreviation":"CSR"}', NULL, 5, 1575, NULL),
(1576, 'corporate strategy', '/ˈkɔːrpərɪt ˈstrætədʒi/', 'noun', '{"zh-TW":["企業策略；公司戰略"],"en":["the overall plan for achieving a company long-term objectives"]}', NULL, 'set corporate strategy / review the corporate strategy', '[{"en":"The board approved a corporate strategy focused on Asia-Pacific growth.","zh-TW":"董事會批准了專注於亞太增長的企業策略。"},{"en":"Corporate strategy guides resource allocation across business units.","zh-TW":"企業策略指導業務部門的資源分配。"}]', NULL, NULL, 5, 1576, NULL),
(1577, 'corporation', 'ˌkɔːrpəˈreɪʃən', 'noun', '{"zh-TW":["公司；企業","法人"],"en":["a large company","a legal entity"]}', NULL, 'large corporation/multinational corporation', '[{"en":"The corporation has offices in 20 countries.","zh-TW":"該企業在20個國家有辦事處。"}]', '{"adjective":"corporate","adverb":"corporately"}', NULL, 4, 1577, 94),
(1578, 'corporatism', '/ˈkɔːrpərɪtɪzəm/', 'noun', '{"zh-TW":["社團主義；公司主義"],"en":["a political system in which society is organized into major interest groups that negotiate with government"]}', NULL, 'state corporatism / liberal corporatism / model of corporatism', '[{"en":"Scandinavian corporatism involves close collaboration between government, employers, and unions.","zh-TW":"斯堪地那維亞的社團主義涉及政府、雇主和工會之間的密切合作。"},{"en":"Critics argue that corporatism blurs the boundary between the state and private enterprise.","zh-TW":"批評者認為，社團主義模糊了國家與私營企業之間的界限。"}]', '{"adjective":"corporatist"}', NULL, 4, 1578, NULL),
(1579, 'correct', '/kəˈrɛkt/', 'adjective', '{"zh-TW":["正確的；糾正","正確的"],"en":["right; without errors","to make right","right; without mistakes"]}', NULL, 'correct answer / correct a mistake; correct answer / politically correct', '[{"en":"Is this information correct?","zh-TW":"這個資訊正確嗎？"},{"en":"Please correct any errors in the report.","zh-TW":"請更正報告中的錯誤。"},{"en":"Your answer is correct.","zh-TW":"你的答案是正確的。"},{"en":"Please correct any errors.","zh-TW":"請改正任何錯誤。"}]', '{"adjective":"correct","verb":"correct","noun":"correction","adverb":"correctly"}', NULL, 3, 1579, 313),
(1580, 'correction', 'kəˈrɛkʃən', 'noun', '{"zh-TW":["更正；修正","訂正"],"en":["a change to fix an error","something that makes something right"]}', NULL, 'make a correction/correction notice', '[{"en":"Please note the correction in paragraph 3.","zh-TW":"請注意第3段的更正。"}]', '{"verb":"correct","adjective":"correct","adverb":"correctly"}', NULL, 4, 1580, NULL),
(1581, 'corrective action', '/kəˈrektɪv ˈækʃən/', 'noun', '{"zh-TW":["矯正措施"],"en":["a step taken to fix the root cause of a problem"]}', NULL, 'take corrective action / corrective action plan / corrective action report', '[{"en":"Corrective action was implemented to prevent the defect from recurring.","zh-TW":"採取了矯正措施以防止缺陷再次發生。"},{"en":"The audit required corrective action on five compliance issues.","zh-TW":"審計要求對五個合規問題採取矯正措施。"}]', '{"adjective":"corrective"}', NULL, 5, 1581, NULL),
(1582, 'correlation', '/ˌkɒrəˈleɪʃən/', 'noun', '{"zh-TW":["相關性；關聯"],"en":["a mutual relationship or connection between two things"]}', NULL, 'positive correlation / negative correlation / strong correlation', '[{"en":"There is a strong correlation between education and income.","zh-TW":"教育與收入之間存在強烈的相關性。"},{"en":"Correlation does not imply causation in statistical analysis.","zh-TW":"在統計分析中，相關性不意味著因果關係。"}]', '{"verb":"correlate","adjective":"correlational"}', NULL, 4, 1582, NULL),
(1583, 'correspond', '/ˌkɒrɪˈspɒnd/', 'verb', '{"zh-TW":["對應；通信"],"en":["to be similar or equivalent to","to communicate by letter or email"]}', '{"prefix":{"text":"cor-","meaning":"together (一起)"},"root":{"text":"respond","meaning":"answer (回應)"},"logic":"一起回應，即「對應、通信」。"}', 'correspond to/with / correspond by email', '[{"en":"The results correspond to our initial predictions.","zh-TW":"結果與我們最初的預測相符。"},{"en":"We have been corresponding by email for months.","zh-TW":"我們已通過電子郵件通信數月。"}]', '{"noun":"correspondence"}', NULL, 4, 1583, 95),
(1584, 'correspondence', '/ˌkɒrɪˈspɒndəns/', 'noun', '{"zh-TW":["通訊；信件往來"],"en":["written communication, especially letters and emails in a business context"]}', NULL, 'business correspondence / official correspondence / maintain correspondence', '[{"en":"All correspondence with clients must be professional and timely.","zh-TW":"與客戶的所有通訊必須專業且及時。"},{"en":"She reviewed the correspondence before the meeting.","zh-TW":"她在會議前審閱了通訊記錄。"}]', '{"verb":"correspond","noun":"correspondent","adjective":"corresponding"}', NULL, 5, 1584, 535),
(1585, 'corroborate', '/kəˈrɒbəreɪt/', 'verb', '{"zh-TW":["證實；支持（陳述）"],"en":["to confirm or give support to a statement or theory"]}', NULL, 'corroborate evidence / corroborate findings / corroborate a claim', '[{"en":"The experiment results corroborate the original hypothesis.","zh-TW":"實驗結果證實了最初的假設。"},{"en":"Two independent witnesses corroborated her account.","zh-TW":"兩位獨立的證人證實了她的陳述。"}]', '{"noun":"corroboration","adjective":"corroborative"}', NULL, 4, 1585, NULL),
(1586, 'cost', '/kɒst/', 'noun', '{"zh-TW":["成本；費用"],"en":["the amount of money needed to buy or do something"]}', '{"root":{"text":"cost","meaning":"stand at a price (定價)"},"logic":"定價，即「成本」。"}', 'cost-effective / at all costs / reduce costs', '[{"en":"We need to reduce operating costs by 15%.","zh-TW":"我們需要將營運成本降低15%。"},{"en":"The total cost exceeded the original estimate.","zh-TW":"總成本超過了原始估算。"}]', '{"adjective":"costly"}', NULL, 1, 1586, NULL),
(1587, 'cost allocation', '/kɒst ˌæləˈkeɪʃən/', 'noun', '{"zh-TW":["成本分配；費用分攤"],"en":["the process of assigning costs to departments, products, or projects"]}', NULL, 'implement cost allocation / cost allocation method', '[{"en":"A fair cost allocation method is essential for accurate product pricing.","zh-TW":"公平的成本分配方法對準確的產品定價至關重要。"},{"en":"The finance team revised the cost allocation formula for shared services.","zh-TW":"財務團隊修訂了共享服務的成本分配公式。"}]', NULL, NULL, 5, 1587, NULL),
(1588, 'cost benefit', '/kɒst ˈbenɪfɪt/', 'noun', '{"zh-TW":["成本效益"],"en":["the analysis of whether the benefits of an action justify its costs"]}', NULL, 'conduct a cost benefit analysis / cost benefit ratio', '[{"en":"A cost benefit analysis showed the investment would yield positive returns.","zh-TW":"成本效益分析顯示投資將帶來正回報。"},{"en":"The team evaluated the cost benefit before upgrading the software.","zh-TW":"團隊在升級軟件前評估了成本效益。"}]', NULL, NULL, 4, 1588, NULL),
(1589, 'cost center', '/kɒst ˈsentər/', 'noun', '{"zh-TW":["成本中心"],"en":["a department or function that incurs costs but does not directly generate revenue"]}', NULL, 'manage a cost center / cost center reporting', '[{"en":"The IT department operates as a cost center within the company.","zh-TW":"IT部門作為公司內的成本中心運作。"},{"en":"Cost center budgets are reviewed quarterly to control expenditure.","zh-TW":"成本中心預算每季度審查一次以控制支出。"}]', '{"opposite":"profit center"}', NULL, 4, 1589, NULL),
(1590, 'cost centre', '/kɒst ˈsentər/', 'noun', '{"zh-TW":["成本中心"],"en":["a department where costs are tracked but revenue is not generated directly"]}', NULL, 'manage a cost centre / cost centre budget', '[{"en":"The IT department operates as a cost centre within the organization.","zh-TW":"IT部門作為組織內的成本中心運營。"},{"en":"Cost centre managers must justify all expenditure requests.","zh-TW":"成本中心管理者必須為所有支出申請提供理由。"}]', NULL, NULL, 4, 1590, NULL),
(1591, 'cost driver', '/kɒst ˈdraɪvər/', 'noun', '{"zh-TW":["成本動因；成本驅動因素"],"en":["an activity or factor that causes changes in the cost of a business activity"]}', NULL, 'identify cost drivers / analyze cost drivers', '[{"en":"Labor hours are the primary cost driver in this manufacturing process.","zh-TW":"勞動時間是此製造流程中的主要成本動因。"},{"en":"Understanding cost drivers enables more accurate budgeting.","zh-TW":"了解成本動因能夠實現更準確的預算編製。"}]', NULL, NULL, 4, 1591, NULL),
(1592, 'cost leadership', '/kɒst ˈliːdərʃɪp/', 'noun', '{"zh-TW":["成本領導；成本優勢戰略"],"en":["a competitive strategy of being the lowest-cost producer in an industry"]}', NULL, 'pursue cost leadership / cost leadership strategy', '[{"en":"The company pursued a cost leadership strategy through lean production.","zh-TW":"公司通過精益生產追求成本領導戰略。"},{"en":"Cost leadership enables the firm to undercut competitor prices.","zh-TW":"成本領導使公司能夠以低於競爭對手的價格銷售。"}]', NULL, NULL, 5, 1592, NULL),
(1593, 'cost of capital', '/kɒst əv ˈkæpɪtəl/', 'noun', '{"zh-TW":["資本成本"],"en":["the required return for a company to justify an investment"]}', NULL, 'calculate cost of capital / weighted average cost of capital / reduce cost of capital', '[{"en":"Projects must exceed the company''s cost of capital to create value.","zh-TW":"項目必須超過公司的資本成本才能創造價值。"},{"en":"A lower credit rating increases the cost of capital for borrowers.","zh-TW":"較低的信用評級提高了借款人的資本成本。"}]', NULL, NULL, 5, 1593, NULL),
(1594, 'cost of goods sold', '/kɒst əv ɡʊdz soʊld/', 'noun', '{"zh-TW":["銷貨成本"],"en":["the direct costs of producing goods sold by a company"]}', NULL, 'calculate cost of goods sold / reduce cost of goods sold', '[{"en":"Cost of goods sold increased due to rising material prices.","zh-TW":"由於材料價格上漲，銷貨成本增加了。"},{"en":"Gross profit is revenue minus cost of goods sold.","zh-TW":"毛利是收入減去銷貨成本。"}]', '{"abbreviation":"COGS"}', NULL, 5, 1594, NULL),
(1595, 'cost overrun', '/kɒst ˈoʊvərʌn/', 'noun', '{"zh-TW":["成本超支；費用超支"],"en":["when actual costs exceed the budgeted amount"]}', NULL, 'experience a cost overrun / prevent cost overruns', '[{"en":"The construction project suffered a 2 million cost overrun.","zh-TW":"建設項目遭遇了200萬元的成本超支。"},{"en":"Poor planning was identified as the main cause of the cost overrun.","zh-TW":"計劃不當被確定為成本超支的主要原因。"}]', NULL, NULL, 4, 1595, NULL),
(1596, 'cost per acquisition', '/kɒst pər ˌækwɪˈzɪʃən/', 'noun', '{"zh-TW":["每次轉換費用；獲客成本"],"en":["the cost of acquiring one paying customer through a campaign"]}', NULL, 'reduce cost per acquisition / target cost per acquisition', '[{"en":"The cost per acquisition dropped after optimizing the landing page.","zh-TW":"優化登陸頁面後，每次轉換費用下降了。"},{"en":"Tracking cost per acquisition helps allocate marketing budget effectively.","zh-TW":"追蹤每次轉換費用有助於有效分配行銷預算。"}]', '{"abbreviation":"CPA"}', NULL, 5, 1596, NULL),
(1597, 'cost per click', '/kɒst pər klɪk/', 'noun', '{"zh-TW":["每次點擊費用"],"en":["the amount paid each time a user clicks on an advertisement"]}', NULL, 'reduce cost per click / average cost per click / optimize cost per click', '[{"en":"The campaign achieved a cost per click of $0.50.","zh-TW":"該活動實現了每次點擊0.50美元的費用。"},{"en":"A/B testing reduced cost per click by 25%.","zh-TW":"A/B測試將每次點擊費用降低了25%。"}]', '{"abbreviation":"CPC"}', NULL, 5, 1597, NULL),
(1598, 'cost recovery', '/kɒst rɪˈkʌvəri/', 'noun', '{"zh-TW":["成本回收"],"en":["recouping money already spent through revenue or savings"]}', NULL, 'achieve cost recovery / full cost recovery', '[{"en":"The project reached full cost recovery in its third year.","zh-TW":"項目在第三年達到了完全成本回收。"},{"en":"Cost recovery is built into the pricing model from the start.","zh-TW":"成本回收從一開始就被納入了定價模型。"}]', NULL, NULL, 5, 1598, NULL),
(1599, 'cost reduction', '/kɒst rɪˈdʌkʃən/', 'noun', '{"zh-TW":["成本削減；降低成本"],"en":["strategies and actions taken to lower operating costs"]}', NULL, 'cost reduction initiative / cost reduction target / achieve cost reduction', '[{"en":"The cost reduction program saved $10 million annually.","zh-TW":"成本削減計劃每年節省了1000萬美元。"},{"en":"Automation is the primary driver of cost reduction in manufacturing.","zh-TW":"自動化是製造業成本削減的主要驅動力。"}]', '{"verb":"reduce costs"}', NULL, 5, 1599, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(1600, 'cost reduction initiative', '/kɒst rɪˈdʌkʃən ɪˈnɪʃɪətɪv/', 'noun', '{"zh-TW":["降成本計劃"],"en":["a structured effort to reduce operating costs without harming output quality"]}', NULL, 'launch a cost reduction initiative / cost reduction initiative results', '[{"en":"The cost reduction initiative saved 10% on annual operating expenses.","zh-TW":"降成本計劃節省了年度運營費用的10%。"},{"en":"All department heads were tasked with contributing to the cost reduction initiative.","zh-TW":"所有部門主管被要求為降成本計劃做出貢獻。"}]', NULL, NULL, 5, 1600, NULL),
(1601, 'cost-benefit analysis', '/kɒst ˈbɛnɪfɪt əˈnæləsɪs/', 'noun', '{"zh-TW":["成本效益分析"],"en":["an evaluation comparing costs and expected benefits of a decision"]}', NULL, 'conduct a cost-benefit analysis / cost-benefit analysis report', '[{"en":"A cost-benefit analysis was conducted before the project was approved.","zh-TW":"項目批准前進行了成本效益分析。"},{"en":"The results of the cost-benefit analysis favored the new system.","zh-TW":"成本效益分析的結果支持採用新系統。"}]', NULL, NULL, 5, 1601, NULL),
(1602, 'cost-benefit ratio', '/kɒst ˈbenɪfɪt ˈreɪʃioʊ/', 'noun', '{"zh-TW":["成本效益比"],"en":["the ratio comparing the costs of a project to its expected financial benefits"]}', NULL, 'calculate the cost-benefit ratio / favorable cost-benefit ratio', '[{"en":"A cost-benefit ratio below 1 indicates expected benefits exceed costs.","zh-TW":"低於1的成本效益比表明預期效益超過了成本。"},{"en":"The project was approved based on a strong cost-benefit ratio.","zh-TW":"項目基於強勁的成本效益比獲得了批准。"}]', NULL, NULL, 5, 1602, NULL),
(1603, 'cost-effective', 'kɒst ɪˈfɛktɪv', 'adjective', '{"zh-TW":["具有成本效益的；划算的","經濟實惠的"],"en":["giving good value for money","efficient use of resources"]}', NULL, 'cost-effective solution/cost-effective approach', '[{"en":"This is the most cost-effective option.","zh-TW":"這是最具成本效益的選項。"}]', '{"noun":"cost-effectiveness","adverb":"cost-effectively"}', NULL, 5, 1603, NULL),
(1604, 'costs', 'kɒsts', 'noun', '{"zh-TW":["費用；成本","代價"],"en":["amounts paid for goods","expenses"]}', NULL, 'operating costs/reduce costs', '[{"en":"We must control operating costs.","zh-TW":"我們必須控制運營成本。"}]', '{"verb":"cost","adjective":"costly","adverb":"costlily"}', NULL, 2, 1604, NULL),
(1605, 'cotton', '/ˈkɒtən/', 'noun', '{"zh-TW":["棉花；棉布"],"en":["a soft white material used for making cloth"]}', NULL, 'cotton shirt / cotton candy', '[{"en":"This shirt is made of cotton.","zh-TW":"這件襯衫是棉做的。"},{"en":"Cotton is grown in warm climates.","zh-TW":"棉花生長在溫暖的氣候中。"}]', NULL, NULL, 2, 1605, NULL),
(1606, 'council', '/ˈkaʊnsl/', 'noun', '{"zh-TW":["委員會；議會"],"en":["an advisory or legislative body of people"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"cil","meaning":"call (召集)"},"logic":"一起被召集的人，即「委員會」。"}', 'city council / council meeting / council member', '[{"en":"The city council approved the new development plan.","zh-TW":"市議會批准了新的開發計畫。"},{"en":"A council meeting is scheduled for next Tuesday.","zh-TW":"委員會會議安排在下週二。"}]', NULL, NULL, 3, 1606, NULL),
(1607, 'counsel', '/ˈkaʊnsl/', 'noun', '{"zh-TW":["勸告；律師","建議"],"en":["advice given formally","a lawyer representing someone"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"sel","meaning":"take/consult (取/諮詢)"},"logic":"一起諮詢，即「勸告」。"}', 'legal counsel / seek counsel / general counsel', '[{"en":"The firm hired outside legal counsel for the case.","zh-TW":"公司為此案聘請了外部法律顧問。"},{"en":"I would counsel patience in this situation.","zh-TW":"我建議在這種情況下保持耐心。"}]', '{"noun":"counselor"}', NULL, 3, 1607, NULL),
(1608, 'count', '/kaʊnt/', 'verb', '{"zh-TW":["【主要意義-動詞/名詞】計算；數數","【次要意義-動詞】重要；有意義；被計入","【次要意義-名詞】（法律）罪名；指控"],"en":["[primary] to calculate the number of something","[secondary - verb] to be significant or valid; to be included","[secondary - noun] a specific charge in a legal case"]}', NULL, 'count on / count toward / every vote counts / count against / on all counts', '[{"en":"Every customer complaint counts toward the quarterly performance review.","zh-TW":"每一個客戶投訴都計入季度績效評估。"},{"en":"Experience in project management will count in your favor.","zh-TW":"專案管理經驗將對你有利。"},{"en":"The defendant was found guilty on all three counts.","zh-TW":"被告在三項罪名上均被裁定有罪。"}]', '{"noun":"recount","adjective":"countless"}', '動詞 count = 「重要/被計入」，count on（依靠），count toward（計入），count against（不利於），這些片語在 TOEIC 商業或法律語境中頻繁出現。', 2, 1608, NULL),
(1609, 'counter', '/ˈkaʊntər/', 'noun', '{"zh-TW":["櫃台；計數器"],"en":["a flat surface in a kitchen or shop"]}', NULL, 'over the counter / counter offer', '[{"en":"Leave the keys on the counter.","zh-TW":"把鑰匙放在櫃台上。"},{"en":"The medicine is available over the counter.","zh-TW":"這個藥不需要處方就能買到。"}]', NULL, NULL, 3, 1609, NULL),
(1610, 'counterargument', '/ˈkaʊntərˌɑːrɡjʊmənt/', 'noun', '{"zh-TW":["反駁論點；對立論據"],"en":["an argument made to oppose or refute another argument"]}', NULL, 'present a counterargument / address the counterargument / strong counterargument', '[{"en":"A good essay must anticipate and address counterarguments.","zh-TW":"一篇好文章必須預見並回應反駁論點。"},{"en":"He raised a compelling counterargument to the prevailing theory.","zh-TW":"他對主流理論提出了一個有力的反駁論點。"}]', NULL, NULL, 5, 1610, NULL),
(1611, 'countercyclical', '/ˌkaʊntərˈsaɪklɪkəl/', 'adjective', '{"zh-TW":["反週期的"],"en":["acting against the economic cycle; increasing during downturns and decreasing during booms"]}', NULL, 'countercyclical policy / countercyclical spending / countercyclical buffer', '[{"en":"Unemployment insurance is a countercyclical stabilizer that supports demand during recessions.","zh-TW":"失業保險是一種反週期穩定器，在衰退期間支持需求。"},{"en":"Countercyclical fiscal policy calls for government spending increases when the economy slows.","zh-TW":"反週期財政政策要求當經濟放緩時增加政府支出。"}]', NULL, NULL, 5, 1611, NULL),
(1612, 'counterfeit goods', '/ˈkaʊntəfɪt ɡʊdz/', 'noun', '{"zh-TW":["假冒商品；仿冒品"],"en":["fake products that imitate a genuine brand without authorization"]}', NULL, 'seize counterfeit goods / combat counterfeit goods', '[{"en":"The customs authority seized a shipment of counterfeit goods.","zh-TW":"海關當局沒收了一批假冒商品。"},{"en":"Counterfeit goods damage brand reputation and reduce revenue.","zh-TW":"假冒商品損害了品牌聲譽並減少了收入。"}]', NULL, NULL, 5, 1612, NULL),
(1613, 'counterintuitive', '/ˌkaʊntərɪnˈtjuːɪtɪv/', 'adjective', '{"zh-TW":["違反直覺的；反直覺的"],"en":["contrary to what one would naturally expect"]}', NULL, 'counterintuitive result / counterintuitive finding / counterintuitive approach', '[{"en":"The counterintuitive result surprised even experienced researchers.","zh-TW":"這個違反直覺的結果甚至讓有經驗的研究員感到驚訝。"},{"en":"It is counterintuitive that stricter policing sometimes increases crime.","zh-TW":"更嚴格的執法有時會增加犯罪率，這是違反直覺的。"}]', '{"adverb":"counterintuitively"}', NULL, 5, 1613, NULL),
(1614, 'counteroffer', '/ˈkaʊntərˌɒfər/', 'noun', '{"zh-TW":["反要約；還價"],"en":["an offer made in response to a previous offer, typically with different terms"]}', NULL, 'make a counteroffer / accept a counteroffer', '[{"en":"The supplier made a counteroffer with a 5% lower price than originally proposed.","zh-TW":"供應商提出了比最初提議低5%的反要約。"},{"en":"The buyer rejected the counteroffer and walked away from the deal.","zh-TW":"買方拒絕了反要約並放棄了交易。"}]', '{"verb":"counteroffer"}', NULL, 4, 1614, NULL),
(1615, 'counterpart', '/ˈkaʊntərpɑːrt/', 'noun', '{"zh-TW":["對應的人或物"],"en":["a person or thing with the same function in a different situation"]}', NULL, 'overseas counterpart / business counterpart', '[{"en":"I met with my Japanese counterpart.","zh-TW":"我與我的日本對口人員會面。"},{"en":"Their product is superior to its counterparts.","zh-TW":"他們的產品優於同類產品。"}]', '{"noun":"counterpart"}', NULL, 4, 1615, 663),
(1616, 'counterparty', '/ˈkaʊntərˌpɑːrti/', 'noun', '{"zh-TW":["對手方；交易對手"],"en":["the other party in a financial transaction or contract"]}', NULL, 'assess counterparty risk / identify the counterparty', '[{"en":"The bank assessed the counterparty''s credit rating before signing.","zh-TW":"銀行在簽署前評估了對手方的信用評級。"},{"en":"Counterparty risk is a major concern in derivatives markets.","zh-TW":"在衍生品市場中，對手方風險是一個主要問題。"}]', NULL, NULL, 4, 1616, NULL),
(1617, 'counterparty risk', '/ˈkaʊntərˌpɑːrti rɪsk/', 'noun', '{"zh-TW":["交易對手風險"],"en":["the risk that the other party in a financial transaction will default"]}', NULL, 'manage counterparty risk / counterparty risk assessment', '[{"en":"Derivatives contracts carry significant counterparty risk if unhedged.","zh-TW":"未對沖的衍生品合約具有顯著的交易對手風險。"},{"en":"Collateral requirements reduce counterparty risk in over-the-counter transactions.","zh-TW":"抵押品要求降低了場外交易中的交易對手風險。"}]', NULL, NULL, 5, 1617, NULL),
(1618, 'country', '/ˈkʌntri/', 'noun', '{"zh-TW":["國家；鄉村"],"en":["a nation","rural areas outside cities","a nation with its own government"]}', NULL, 'home country / country of origin; home country / country side', '[{"en":"Which country are you from?","zh-TW":"你來自哪個國家？"},{"en":"The product''s country of origin is Japan.","zh-TW":"產品的原產國是日本。"},{"en":"They live in the countryside.","zh-TW":"他們住在鄉下。"}]', '{"noun":"country","noun2":"countryside"}', NULL, 3, 1618, NULL),
(1619, 'county', '/ˈkaʊnti/', 'noun', '{"zh-TW":["郡；縣"],"en":["a region of a country"]}', NULL, 'county court / county fair', '[{"en":"She lives in Orange County.","zh-TW":"她住在橘郡。"},{"en":"The county fair is in August.","zh-TW":"縣集市在八月舉行。"}]', NULL, NULL, 2, 1619, NULL),
(1620, 'couple', '/ˈkʌpəl/', 'noun', '{"zh-TW":["一對；幾個","一對；一些"],"en":["two people together","a small number","two people together; a few"]}', NULL, 'a couple of / married couple', '[{"en":"I need a couple of days to finish.","zh-TW":"我需要幾天來完成。"},{"en":"The couple next door just moved in.","zh-TW":"隔壁那對夫妻剛搬進來。"},{"en":"A couple of days ago, I saw him.","zh-TW":"幾天前我看到他了。"},{"en":"They make a lovely couple.","zh-TW":"他們是很可愛的一對。"}]', '{"noun":"couple","verb":"couple"}', NULL, 2, 1620, NULL),
(1621, 'coupon', '/ˈkuːpɒn/', 'noun', '{"zh-TW":["優惠券；折價券"],"en":["a voucher giving a discount on a product"]}', '{"root":{"text":"coupon","meaning":"cut piece (切下的紙片)"},"logic":"源自法語 couper（剪），指剪下的折價券。"}', 'discount coupon / redeem a coupon', '[{"en":"I have a coupon for 20% off.","zh-TW":"我有一張八折優惠券。"},{"en":"Customers can redeem coupons at checkout.","zh-TW":"顧客可以在結帳時兌換優惠券。"}]', NULL, NULL, 2, 1621, NULL),
(1622, 'courage', '/ˈkɜːrɪdʒ/', 'noun', '{"zh-TW":["勇氣"],"en":["the ability to face danger without fear"]}', NULL, 'have the courage / take courage', '[{"en":"It takes courage to speak up.","zh-TW":"站出來發言需要勇氣。"},{"en":"She showed great courage.","zh-TW":"她展現了極大的勇氣。"}]', '{"adjective":"courageous"}', NULL, 3, 1622, NULL),
(1623, 'courageous', '/kəˈreɪdʒəs/', 'adjective', '{"zh-TW":["勇敢的"],"en":["not afraid of danger or difficulties"]}', '{"root":{"text":"courage","meaning":"heart (心)"},"suffix":{"text":"-ous","meaning":"full of (充滿)"},"logic":"充滿勇氣的，即「勇敢的」。"}', 'courageous act / courageous decision', '[{"en":"It was a courageous decision to speak up.","zh-TW":"站出來發聲是勇敢的決定。"},{"en":"The firefighters were incredibly courageous.","zh-TW":"消防隊員們非常英勇。"}]', '{"noun":"courage","adverb":"courageously"}', NULL, 4, 1623, NULL),
(1624, 'courier', '/ˈkʊriər/', 'noun', '{"zh-TW":["快遞員；信差"],"en":["a person or company that transports documents or packages quickly"]}', NULL, 'send by courier / courier service / international courier', '[{"en":"The documents were sent by courier to arrive the next morning.","zh-TW":"文件通過快遞發送，次日早上到達。"},{"en":"An international courier service was used to ship the samples.","zh-TW":"使用了國際快遞服務運送樣品。"}]', '{"verb":"courier"}', NULL, 3, 1624, NULL),
(1625, 'courier service', '/ˈkʊriər ˈsɜːrvɪs/', 'noun', '{"zh-TW":["快遞服務；信使服務"],"en":["a service for fast and secure delivery of documents or parcels"]}', NULL, 'use a courier service / courier service charges', '[{"en":"The document was sent by courier service for next-day delivery.","zh-TW":"文件通過快遞服務以次日達方式寄送。"},{"en":"The company uses a courier service for urgent contract deliveries.","zh-TW":"公司使用快遞服務進行緊急合約交付。"}]', NULL, NULL, 5, 1625, NULL),
(1626, 'course', '/kɔːrs/', 'noun', '{"zh-TW":["課程；過程"],"en":["a series of lessons","a direction or path"]}', NULL, 'of course / training course', '[{"en":"I enrolled in a training course.","zh-TW":"我報名了一個培訓課程。"},{"en":"Of course, I will help you.","zh-TW":"當然，我會幫你。"}]', '{"noun":"course"}', NULL, 2, 1626, NULL),
(1627, 'coursework', '/ˈkɔːrswɜːrk/', 'noun', '{"zh-TW":["課程作業；學術作業"],"en":["written or practical work contributing to a final grade"]}', NULL, 'submit coursework / complete coursework', '[{"en":"Her coursework accounts for 40% of the final grade.","zh-TW":"她的課程作業佔最終成績的40%。"},{"en":"Completing coursework on time demonstrates responsibility.","zh-TW":"按時完成課程作業展示了責任感。"}]', NULL, NULL, 4, 1627, NULL),
(1628, 'court', '/kɔːrt/', 'noun', '{"zh-TW":["法庭；球場"],"en":["a place where legal cases are heard"]}', NULL, 'go to court / tennis court', '[{"en":"The case went to court.","zh-TW":"案件上了法庭。"},{"en":"We booked a tennis court.","zh-TW":"我們預訂了一個網球場。"}]', NULL, NULL, 2, 1628, NULL),
(1629, 'courtesy', '/ˈkɜːrtɪsi/', 'noun', '{"zh-TW":["禮貌；禮節"],"en":["polite behavior; or something provided free of charge as a favor"]}', NULL, 'courtesy call / courtesy van', '[{"en":"The hotel provides a courtesy van to the airport.","zh-TW":"飯店提供接送機場的禮賓車。"},{"en":"She received a courtesy call confirming her reservation.","zh-TW":"她收到了確認預訂的禮貌電話。"}]', '{"adjective":"courteous","adverb":"courteously"}', NULL, 3, 1629, NULL),
(1630, 'cousin', '/ˈkʌzən/', 'noun', '{"zh-TW":["表兄弟姊妹"],"en":["the child of your aunt or uncle"]}', NULL, 'first cousin / distant cousin', '[{"en":"My cousin lives in Canada.","zh-TW":"我表哥住在加拿大。"},{"en":"We''re first cousins.","zh-TW":"我們是表兄弟。"}]', NULL, NULL, 2, 1630, NULL),
(1631, 'covenant', '/ˈkʌvənənt/', 'noun', '{"zh-TW":["契約；約定條款"],"en":["a formal agreement or a restriction imposed in a financial contract"]}', NULL, 'financial covenant / loan covenant / breach a covenant', '[{"en":"The loan agreement includes a covenant limiting additional borrowing.","zh-TW":"貸款協議包含限制額外借款的約定條款。"},{"en":"Breaching the financial covenant triggered a review by the lenders.","zh-TW":"違反財務約定條款觸發了貸款方的審查。"}]', '{"verb":"covenant"}', NULL, 3, 1631, NULL),
(1632, 'covenant waiver', '/ˈkʌvənənt ˈweɪvər/', 'noun', '{"zh-TW":["契約豁免"],"en":["a lender''s agreement to temporarily not enforce a covenant the borrower has breached"]}', NULL, 'obtain a covenant waiver / grant a covenant waiver / covenant waiver request', '[{"en":"The company obtained a covenant waiver from its lenders after missing targets.","zh-TW":"公司在未達到目標後從貸款方獲得了契約豁免。"},{"en":"A covenant waiver provides temporary relief but often comes with conditions.","zh-TW":"契約豁免提供臨時緩解，但通常附帶條件。"}]', NULL, NULL, 5, 1632, NULL),
(1633, 'covenant-lite', '/ˈkʌvənənt laɪt/', 'phrase', '{"zh-TW":["寬鬆契約條款的"],"en":["(of a loan) having fewer protective conditions for lenders"]}', NULL, 'covenant-lite loan / covenant-lite deal / covenant-lite structure', '[{"en":"Covenant-lite loans give borrowers more flexibility but expose lenders to greater risk.","zh-TW":"寬鬆契約條款的貸款為借款人提供更多彈性，但使貸款方面臨更大風險。"},{"en":"The leveraged buyout was financed with a covenant-lite credit facility.","zh-TW":"這次槓桿收購以寬鬆契約條款的信貸工具融資。"}]', NULL, NULL, 5, 1633, NULL),
(1634, 'cover', '/ˈkʌvər/', 'verb', '{"zh-TW":["【主要意義-動詞/名詞】覆蓋；封面","【次要意義-動詞】代替（同事）；代班","【次要意義-動詞】涵蓋範圍；包含","【次要意義-名詞】保險保障；掩護"],"en":["[primary] to place something over something else; an outer layer","[secondary - verb] to do someone else job while they are away","[secondary - verb] to include or deal with in scope","[secondary - noun] insurance protection; a pretense for hiding something"]}', NULL, 'cover for someone / cover a story / insurance cover / cover letter / under cover', '[{"en":"Can you cover for me while I attend the training session?","zh-TW":"我參加培訓課程時你能替我代班嗎？"},{"en":"The insurance policy covers all medical expenses incurred abroad.","zh-TW":"保險單涵蓋了在國外產生的所有醫療費用。"},{"en":"The seminar will cover topics ranging from marketing to finance.","zh-TW":"研討會將涵蓋從市場營銷到財務的各種主題。"}]', '{"noun":"coverage","adjective":"undercover"}', 'cover 的次要意義：cover for（代班）、insurance cover（保險保障）、cover letter（求職信）均為 TOEIC 職場文章必考詞彙，考生容易只記住「覆蓋」的意思。', 2, 1634, NULL),
(1635, 'cover letter', '/ˈkʌvər ˈletər/', 'noun', '{"zh-TW":["求職信"],"en":["a letter sent with a résumé expressing interest in a position"]}', NULL, 'write a cover letter / customize a cover letter / strong cover letter', '[{"en":"A compelling cover letter can set a candidate apart from other applicants.","zh-TW":"一封引人注目的求職信能讓候選人從其他申請者中脫穎而出。"},{"en":"She addressed the cover letter directly to the hiring manager.","zh-TW":"她將求職信直接寄給招聘主管。"}]', NULL, NULL, 4, 1635, NULL),
(1636, 'coverage', '/ˈkʌvərɪdʒ/', 'noun', '{"zh-TW":["保險承保範圍"],"en":["the extent of protection provided by insurance"]}', NULL, 'insurance coverage / comprehensive coverage', '[{"en":"Check whether dental care is included in your coverage.","zh-TW":"確認您的保險承保範圍是否包含牙科護理。"},{"en":"Her policy provides coverage for hospitalization.","zh-TW":"她的保單提供住院承保。"}]', '{"verb":"cover","adjective":"covered"}', NULL, 3, 1636, 96),
(1637, 'coverage ratio', '/ˈkʌvərɪdʒ ˈreɪʃioʊ/', 'noun', '{"zh-TW":["覆蓋比率；償債比率"],"en":["a metric measuring a company''s ability to service its financial obligations"]}', NULL, 'calculate coverage ratio / interest coverage ratio', '[{"en":"A coverage ratio above 2 is typically considered financially healthy.","zh-TW":"高於2的覆蓋比率通常被認為財務健康。"},{"en":"Lenders check the coverage ratio before extending credit facilities.","zh-TW":"貸款方在延伸信貸額度前檢查覆蓋比率。"}]', NULL, NULL, 5, 1637, NULL),
(1638, 'cow', '/kaʊ/', 'noun', '{"zh-TW":["牛；母牛"],"en":["a large female farm animal that produces milk"]}', NULL, 'dairy cow / cow milk', '[{"en":"The farmer milks the cows every morning.","zh-TW":"農夫每天早上擠牛奶。"},{"en":"Cows eat grass in the field.","zh-TW":"牛在田裡吃草。"}]', NULL, NULL, 1, 1638, NULL),
(1639, 'coworking space', '/ˈkoʊwɜːrkɪŋ speɪs/', 'noun', '{"zh-TW":["共享辦公空間"],"en":["a shared work environment used by people from different organizations"]}', NULL, 'rent a coworking space / coworking space membership / flexible coworking space', '[{"en":"Startups often begin in coworking spaces to keep costs low.","zh-TW":"新創公司通常從共享辦公空間開始以降低成本。"},{"en":"Coworking spaces provide networking opportunities and amenities.","zh-TW":"共享辦公空間提供社交機會和設施。"}]', NULL, NULL, 5, 1639, NULL),
(1640, 'crack', '/kræk/', 'noun', '{"zh-TW":["【主要意義-動詞/名詞】破裂；裂縫","【次要意義-形容詞】優秀的；一流的；精銳的","【次要意義-動詞】解決（問題）；破解（密碼）","【次要意義-名詞】嘗試；機會（have a crack at）"],"en":["[primary] to break partially; a narrow opening or line of damage","[secondary - adjective] highly skilled or expert","[secondary - verb] to find the solution to something difficult","[secondary - noun] an attempt at something"]}', NULL, 'a crack team / crack the code / crack down on / have a crack at / crack of dawn', '[{"en":"She joined the crack negotiating team sent to close the deal.","zh-TW":"她加入了派去完成交易的精銳談判團隊。"},{"en":"The new software engineers managed to crack the encryption problem.","zh-TW":"新的軟體工程師成功破解了加密問題。"},{"en":"Regulators are cracking down on companies that violate data privacy laws.","zh-TW":"監管機構正在加強打擊違反數據隱私法的公司。"}]', '{"noun":"crackdown","adjective":"cracked"}', '形容詞 crack = 「一流的/精銳的」（a crack team），crack down on（嚴厲打擊），have a crack at（嘗試），均是 TOEIC 商業和法規文章的高頻表達，考生容易只認識名詞「裂縫」。', 2, 1640, NULL),
(1641, 'craft', '/kræft/', 'noun', '{"zh-TW":["工藝；手藝"],"en":["an activity involving skilled making of things by hand","an activity involving skill in making things by hand"]}', '{"root":{"text":"craft","meaning":"strength/skill (力量/技藝)"},"logic":"源自古英語 cræft（力量、技能）。"}', 'arts and crafts / craft beer; arts and crafts / craft beer / master one''s craft', '[{"en":"She''s skilled in traditional crafts.","zh-TW":"她擅長傳統工藝。"},{"en":"Craft beer has become very popular.","zh-TW":"精釀啤酒變得非常受歡迎。"},{"en":"She learned the craft of pottery making.","zh-TW":"她學會了陶藝的手藝。"},{"en":"Local crafts are sold at the market.","zh-TW":"當地手工藝品在市場販售。"}]', '{"noun2":"craftsman","adjective":"crafty","noun":"craftsman","verb":"craft"}', NULL, 2, 1641, NULL),
(1642, 'crash', '/kræʃ/', 'noun', '{"zh-TW":["碰撞；崩潰"],"en":["a violent collision; a sudden failure"]}', NULL, 'car crash / system crash', '[{"en":"There was a car crash on the highway.","zh-TW":"高速公路上發生了車禍。"},{"en":"The computer crashed again.","zh-TW":"電腦又當機了。"}]', '{"verb":"crash"}', NULL, 2, 1642, NULL),
(1643, 'crazy', '/ˈkreɪzi/', 'adjective', '{"zh-TW":["瘋狂的"],"en":["very foolish; mentally ill"]}', NULL, 'go crazy / crazy about', '[{"en":"That''s a crazy idea!","zh-TW":"那是個瘋狂的想法！"},{"en":"She''s crazy about music.","zh-TW":"她對音樂非常著迷。"}]', NULL, NULL, 2, 1643, NULL),
(1644, 'cream', '/kriːm/', 'noun', '{"zh-TW":["奶油；乳霜"],"en":["the thick white liquid from milk"]}', NULL, 'ice cream / cream cheese', '[{"en":"I''d like cream in my coffee.","zh-TW":"我的咖啡要加奶油。"},{"en":"Apply this cream twice daily.","zh-TW":"每天塗兩次這個乳霜。"}]', '{"adjective":"creamy"}', NULL, 2, 1644, NULL),
(1645, 'create', '/kriˈeɪt/', 'verb', '{"zh-TW":["創造；建立"],"en":["to bring something into existence"]}', '{"root":{"text":"cre","meaning":"grow/make (成長/製造)"},"suffix":{"text":"-ate","meaning":"to do (做)"},"logic":"使成長出來，即「創造」。"}', 'create value/opportunities/jobs', '[{"en":"The merger will create the largest company in the sector.","zh-TW":"合併將創建該行業最大的公司。"},{"en":"Innovation creates new business opportunities.","zh-TW":"創新創造了新的商業機會。"}]', '{"noun":"creation","adjective":"creative","noun2":"creativity"}', NULL, 2, 1645, 314),
(1646, 'creative', '/kriˈeɪtɪv/', 'adjective', '{"zh-TW":["有創意的"],"en":["involving the use of imagination to produce new ideas"]}', '{"root":{"text":"creat","meaning":"make (創造)"},"suffix":{"text":"-ive","meaning":"having quality of (具有…特質)"},"logic":"具有創造特質的。"}', 'creative thinking / creative director', '[{"en":"She found a creative solution to the problem.","zh-TW":"她找到了一個有創意的解決方案。"},{"en":"The job requires creative thinking.","zh-TW":"這份工作需要創意思考。"}]', '{"noun":"creativity","verb":"create","noun2":"creation"}', NULL, 3, 1646, NULL),
(1647, 'creature', '/ˈkriːtʃər/', 'noun', '{"zh-TW":["生物；動物"],"en":["any living thing that is not a plant"]}', NULL, 'living creature / sea creature', '[{"en":"Strange creatures live in the deep sea.","zh-TW":"奇怪的生物生活在深海中。"},{"en":"Every creature deserves respect.","zh-TW":"每一個生物都值得被尊重。"}]', NULL, NULL, 3, 1647, NULL),
(1648, 'credential', '/krɪˈdɛnʃəl/', 'noun', '{"zh-TW":["資格證明；證書"],"en":["qualifications or achievements that prove capability"]}', NULL, 'professional credentials / verify credentials', '[{"en":"Please verify the candidate''s credentials.","zh-TW":"請驗證候選人的資歷。"},{"en":"His credentials include an MBA and CPA.","zh-TW":"他的資歷包括MBA和CPA。"}]', '{"noun":"credential","adjective":"credentialed"}', NULL, 4, 1648, NULL),
(1649, 'credibility', '/ˌkredɪˈbɪlɪti/', 'noun', '{"zh-TW":["可信度；信譽"],"en":["the quality of being trusted and believed in"]}', NULL, 'build credibility / establish credibility / credibility with investors', '[{"en":"The auditor''s report added credibility to the financial statements.","zh-TW":"審計師的報告增加了財務報表的可信度。"},{"en":"A strong track record builds credibility with customers and partners.","zh-TW":"強勁的業績記錄建立了對客戶和合作夥伴的信譽。"}]', '{"adjective":"credible","adverb":"credibly"}', NULL, 4, 1649, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(1650, 'credit', '/ˈkredɪt/', 'noun', '{"zh-TW":["信用；學分","功勞","信用；學分；功勞"],"en":["the ability to borrow money","praise or acknowledgment","the ability to buy now and pay later"]}', '{"root":{"text":"cred","meaning":"believe (相信)"},"suffix":{"text":"-it","meaning":"thing (事物)"},"logic":"被相信（可還款）的，即「信用」。"}', 'credit card / credit rating / take credit for; credit card / take credit', '[{"en":"The company has a strong credit rating.","zh-TW":"公司擁有良好的信用評級。"},{"en":"Credit sales increased by 12% this quarter.","zh-TW":"本季度信用銷售增長了12%。"},{"en":"She paid by credit card.","zh-TW":"她用信用卡付款。"},{"en":"Give credit where it''s due.","zh-TW":"該給的功勞要給。"}]', '{"noun":"creditor","adjective":"credible","verb":"credit","noun2":"creditor"}', NULL, 2, 1650, NULL),
(1651, 'credit analysis', '/ˈkredɪt əˈnæləsɪs/', 'noun', '{"zh-TW":["信用分析"],"en":["the evaluation of a borrower''s financial strength and ability to repay debt"]}', NULL, 'conduct credit analysis / credit analysis report', '[{"en":"A thorough credit analysis is conducted before approving any large loan.","zh-TW":"在批准任何大額貸款之前進行全面的信用分析。"},{"en":"Credit analysis involves reviewing financial statements and cash flow projections.","zh-TW":"信用分析涉及審查財務報表和現金流量預測。"}]', NULL, NULL, 5, 1651, NULL),
(1652, 'credit assessment', '/ˈkredɪt əˈsesmənt/', 'noun', '{"zh-TW":["信用評估"],"en":["the process of evaluating a borrower''s ability and willingness to repay debt"]}', NULL, 'conduct a credit assessment / credit assessment score', '[{"en":"Banks conduct a credit assessment before approving a loan application.","zh-TW":"銀行在批准貸款申請前進行信用評估。"},{"en":"A poor credit assessment result leads to higher interest rates or rejection.","zh-TW":"信用評估結果不佳會導致更高的利率或被拒絕。"}]', NULL, NULL, 5, 1652, NULL),
(1653, 'credit card', '/ˈkrɛdɪt kɑːrd/', 'noun', '{"zh-TW":["信用卡"],"en":["a card that allows purchases on credit"]}', NULL, 'pay by credit card / credit card limit', '[{"en":"She paid for the hotel room using her credit card.","zh-TW":"她使用信用卡支付了飯店房費。"},{"en":"Check your credit card statement regularly for errors.","zh-TW":"定期查看您的信用卡帳單以確認是否有錯誤。"}]', NULL, NULL, 4, 1653, NULL),
(1654, 'credit default swap', '/ˈkredɪt dɪˈfɔːlt swɒp/', 'noun', '{"zh-TW":["信貸違約互換"],"en":["a financial instrument allowing the transfer of credit risk from buyer to seller"]}', NULL, 'purchase a credit default swap / credit default swap premium', '[{"en":"Banks use credit default swaps to hedge against borrower default risk.","zh-TW":"銀行使用信貸違約互換對沖借款人違約風險。"},{"en":"Credit default swaps were at the centre of the 2008 financial crisis.","zh-TW":"信貸違約互換是2008年金融危機的核心。"}]', '{"abbreviation":"CDS"}', NULL, 5, 1654, NULL),
(1655, 'credit exposure', '/ˈkredɪt ɪkˈspoʊʒər/', 'noun', '{"zh-TW":["信用敞口"],"en":["the total amount of risk a lender or investor has to a specific borrower or counterparty"]}', NULL, 'limit credit exposure / credit exposure management', '[{"en":"The bank limited its credit exposure to a single borrower to 10% of capital.","zh-TW":"銀行將對單個借款人的信用敞口限制在資本的10%。"},{"en":"Credit exposure must be monitored across all derivative and lending positions.","zh-TW":"信用敞口必須在所有衍生品和貸款倉位中進行監控。"}]', NULL, NULL, 5, 1655, NULL),
(1656, 'credit facility', '/ˈkredɪt fəˈsɪlɪti/', 'noun', '{"zh-TW":["信貸額度；授信額度"],"en":["a pre-approved loan arrangement allowing borrowing up to a set limit"]}', NULL, 'revolving credit facility / credit facility limit / draw on a credit facility', '[{"en":"The company drew on its credit facility to cover operating expenses.","zh-TW":"公司動用了信貸額度來支付運營費用。"},{"en":"A credit facility provides flexible access to funds when needed.","zh-TW":"信貸額度在需要時提供靈活的資金存取。"}]', NULL, NULL, 5, 1656, NULL),
(1657, 'credit hour', '/ˈkrɛdɪt ˈaʊər/', 'noun', '{"zh-TW":["學分小時；修課學分"],"en":["a unit measuring the amount of study at a college"]}', NULL, 'earn credit hours / required credit hours', '[{"en":"The degree requires a total of 120 credit hours.","zh-TW":"該學位需要總共120個學分。"},{"en":"Students typically take 15 credit hours per semester.","zh-TW":"學生每學期通常修讀15個學分。"}]', NULL, NULL, 4, 1657, NULL),
(1658, 'credit insurance', '/ˈkredɪt ɪnˈʃʊərəns/', 'noun', '{"zh-TW":["信用保險"],"en":["insurance protecting a lender or seller against the risk of non-payment"]}', NULL, 'purchase credit insurance / credit insurance policy', '[{"en":"The exporter bought credit insurance to protect against buyer default.","zh-TW":"出口商購買了信用保險以防範買方違約。"},{"en":"Credit insurance covers both commercial and political payment risks.","zh-TW":"信用保險涵蓋了商業和政治支付風險。"}]', NULL, NULL, 5, 1658, NULL),
(1659, 'credit limit', '/ˈkrɛdɪt ˈlɪmɪt/', 'noun', '{"zh-TW":["信用額度"],"en":["the maximum amount that can be borrowed on a credit line"]}', NULL, 'increase the credit limit / credit limit exceeded', '[{"en":"Her credit limit was increased after a year of good standing.","zh-TW":"她在一年的良好記錄後信用額度得到提升。"},{"en":"The transaction was declined because the credit limit was exceeded.","zh-TW":"交易因超出信用額度而被拒絕。"}]', NULL, NULL, 4, 1659, NULL),
(1660, 'credit management', '/ˈkredɪt ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["信用管理"],"en":["the process of controlling credit extended to customers and managing collections"]}', NULL, 'implement credit management / credit management policy', '[{"en":"Strong credit management reduces bad debt and improves cash flow.","zh-TW":"強有力的信用管理減少了壞帳並改善了現金流。"},{"en":"The credit management team sets limits and monitors customer accounts.","zh-TW":"信用管理團隊設置限額並監控客戶帳戶。"}]', NULL, NULL, 5, 1660, NULL),
(1661, 'credit note', '/ˈkrɛdɪt nəʊt/', 'noun', '{"zh-TW":["貸項通知單；退款憑單"],"en":["a document issued for goods returned or a billing error"]}', NULL, 'issue a credit note / receive a credit note', '[{"en":"The supplier issued a credit note for the returned goods.","zh-TW":"供應商為退貨發出了貸項通知單。"},{"en":"Apply the credit note to your next invoice.","zh-TW":"將貸項通知單應用於您的下一張發票。"}]', NULL, NULL, 4, 1661, NULL),
(1662, 'credit rating', '/ˈkredɪt ˈreɪtɪŋ/', 'noun', '{"zh-TW":["信用評級"],"en":["an assessment of a borrower''s ability to repay debt"]}', NULL, 'credit rating upgrade / credit rating downgrade / maintain credit rating', '[{"en":"The firm''s credit rating was downgraded after the profit warning.","zh-TW":"公司在發出盈利警告後，信用評級被下調。"},{"en":"A strong credit rating lowers borrowing costs for businesses.","zh-TW":"強勁的信用評級降低了企業的借貸成本。"}]', '{"noun":"credit rating agency"}', NULL, 5, 1662, NULL),
(1663, 'credit score', '/ˈkrɛdɪt skɔːr/', 'noun', '{"zh-TW":["信用評分"],"en":["a numerical representation of a person''s creditworthiness"]}', NULL, 'improve a credit score / check credit score', '[{"en":"A high credit score makes it easier to get a loan.","zh-TW":"高信用評分使獲得貸款更容易。"},{"en":"Missing payments can significantly lower your credit score.","zh-TW":"錯過付款可能大幅降低您的信用評分。"}]', NULL, NULL, 4, 1663, NULL),
(1664, 'credit worthiness', '/ˈkredɪt ˈwɜːrðɪnɪs/', 'noun', '{"zh-TW":["信用度；信用狀況"],"en":["the assessment of a borrower''s ability and willingness to repay debt"]}', NULL, 'assess creditworthiness / creditworthiness score', '[{"en":"Banks evaluate creditworthiness before approving a business loan.","zh-TW":"銀行在批准商業貸款前評估信用度。"},{"en":"A strong credit history improves a company''s creditworthiness rating.","zh-TW":"強大的信用歷史改善了公司的信用度評級。"}]', '{"adjective":"creditworthy"}', NULL, 5, 1664, NULL),
(1665, 'creditor', '/ˈkredɪtər/', 'noun', '{"zh-TW":["債權人；貸款方"],"en":["a person or company to whom money is owed"]}', NULL, 'secured creditor / unsecured creditor / creditor rights', '[{"en":"Creditors were notified of the company''s insolvency.","zh-TW":"債權人被告知公司的資不抵債情況。"},{"en":"The bank is a major creditor of the struggling retailer.","zh-TW":"銀行是這家陷入困境的零售商的主要債權人。"}]', '{"opposite":"debtor"}', NULL, 3, 1665, NULL),
(1666, 'creditworthy', '/ˈkredɪtˌwɜːrði/', 'adjective', '{"zh-TW":["信用良好的；值得信貸的"],"en":["considered likely to repay loans reliably"]}', NULL, 'creditworthy borrower / assess creditworthiness', '[{"en":"Only creditworthy applicants are approved for the credit facility.","zh-TW":"只有信用良好的申請者才能獲批信貸額度。"},{"en":"The company worked to become more creditworthy by reducing debt.","zh-TW":"公司通過減少債務來提高其信用水準。"}]', '{"noun":"creditworthiness"}', NULL, 4, 1666, NULL),
(1667, 'crew', '/kruː/', 'noun', '{"zh-TW":["全體船員；團隊"],"en":["a group of people working together"]}', NULL, 'flight crew / camera crew', '[{"en":"The flight crew was very friendly.","zh-TW":"機組人員非常友善。"},{"en":"The film crew arrived early.","zh-TW":"攝影團隊很早就到了。"}]', NULL, NULL, 1, 1667, NULL),
(1668, 'crime', '/kraɪm/', 'noun', '{"zh-TW":["犯罪；罪行"],"en":["an illegal act"]}', NULL, 'commit a crime / crime rate', '[{"en":"Crime rates have decreased.","zh-TW":"犯罪率下降了。"},{"en":"He committed a serious crime.","zh-TW":"他犯了嚴重的罪行。"}]', '{"noun2":"criminal","adjective":"criminal"}', NULL, 2, 1668, NULL),
(1669, 'criminal', '/ˈkrɪmɪnəl/', 'noun', '{"zh-TW":["罪犯"],"en":["a person who has committed a crime"]}', NULL, 'criminal record / criminal law', '[{"en":"The criminal was arrested.","zh-TW":"罪犯被逮捕了。"},{"en":"He has a criminal record.","zh-TW":"他有犯罪紀錄。"}]', '{"noun2":"crime","adjective":"criminal"}', NULL, 3, 1669, NULL),
(1670, 'crisis', '/ˈkraɪsɪs/', 'noun', '{"zh-TW":["危機"],"en":["a time of great difficulty or danger"]}', NULL, 'financial crisis / crisis management', '[{"en":"The country is facing an economic crisis.","zh-TW":"國家正面臨經濟危機。"},{"en":"Good leaders handle crises well.","zh-TW":"好的領導者善於處理危機。"}]', NULL, NULL, 2, 1670, NULL),
(1671, 'crisis management', '/ˈkraɪsɪs ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["危機管理"],"en":["the process of preparing for and responding to a crisis"]}', NULL, 'crisis management plan / effective crisis management / crisis management team', '[{"en":"The CEO praised the team''s crisis management during the recall.","zh-TW":"執行長稱讚了團隊在召回期間的危機管理。"},{"en":"A crisis management plan should be tested regularly.","zh-TW":"危機管理計劃應定期測試。"}]', '{"noun":"crisis manager"}', NULL, 5, 1671, NULL),
(1672, 'criteria', '/kraɪˈtɪəriə/', 'noun', '{"zh-TW":["標準；準則（複數）","標準（複數）"],"en":["standards by which something is judged","principles used to judge or decide something"]}', '{"root":{"text":"crit","meaning":"judge (判斷)"},"suffix":{"text":"-eria","meaning":"plural (複數)"},"logic":"用來判斷的標準，即「準則」。"}', 'meet criteria / selection criteria / evaluation criteria; meet the criteria / selection criteria / strict criteria', '[{"en":"Applicants must meet all the selection criteria.","zh-TW":"申請者必須符合所有篩選標準。"},{"en":"What criteria did you use to evaluate the proposals?","zh-TW":"你用什麼標準來評估提案？"},{"en":"Applicants must meet all the criteria.","zh-TW":"申請者必須符合所有標準。"},{"en":"What criteria did you use to make the decision?","zh-TW":"你用什麼標準做出決定？"}]', '{"noun":"criterion","noun_singular":"criterion"}', NULL, 3, 1672, 315),
(1673, 'criterion', '/kraɪˈtɪəriən/', 'noun', '{"zh-TW":["標準；準則（單數）"],"en":["a principle or standard by which something is judged"]}', '{"root":{"text":"crit","meaning":"judge (判斷)"},"suffix":{"text":"-erion","meaning":"thing (事物)"},"logic":"用來判斷的事物，即「標準」。"}', 'main criterion / selection criterion / meet the criterion', '[{"en":"Price is not the only criterion for selection.","zh-TW":"價格不是選擇的唯一標準。"},{"en":"The main criterion is prior experience.","zh-TW":"主要標準是先前的經驗。"}]', '{"noun":"criteria"}', NULL, 3, 1673, NULL),
(1674, 'critic', '/ˈkrɪtɪk/', 'noun', '{"zh-TW":["評論家；批評者"],"en":["a person who judges the quality of art, music, or literature"]}', '{"root":{"text":"crit","meaning":"judge (判斷)"},"suffix":{"text":"-ic","meaning":"person (人)"},"logic":"做出判斷的人，即「評論家」。"}', 'film critic / art critic / harsh critic', '[{"en":"The critics praised the new film.","zh-TW":"影評人稱讚這部新電影。"},{"en":"He is a well-known food critic.","zh-TW":"他是知名的美食評論家。"}]', '{"noun":"criticism","adjective":"critical","verb":"criticize"}', NULL, 2, 1674, NULL),
(1675, 'critical', '/ˈkrɪtɪkəl/', 'adjective', '{"zh-TW":["批評的；關鍵的；危急的"],"en":["very important; expressing disapproval"]}', NULL, 'critical thinking / critical condition', '[{"en":"Critical thinking is an essential skill.","zh-TW":"批判性思維是必備技能。"},{"en":"The patient is in critical condition.","zh-TW":"病人情況危急。"}]', '{"noun":"criticism","verb":"criticize","noun2":"critic"}', NULL, 3, 1675, 848),
(1676, 'critical analysis', '/''krɪtɪkəl əˌnæləsɪs/', 'noun', '{"zh-TW":["批判性分析"],"en":["the examination of a subject or work to understand its structure, meaning, or nature"]}', NULL, 'conduct a critical analysis / submit a critical analysis / critical analysis essay', '[{"en":"The assignment required a critical analysis of three scientific research papers.","zh-TW":"作業要求對三篇科學研究論文進行批判性分析。"},{"en":"A critical analysis involves evaluating both the strengths and weaknesses of an argument.","zh-TW":"批判性分析涉及評估論點的優點和缺點。"}]', NULL, NULL, 5, 1676, NULL),
(1677, 'critical path', '/ˈkrɪtɪkəl pɑːθ/', 'noun', '{"zh-TW":["關鍵路徑"],"en":["the longest sequence of dependent tasks determining a project''s minimum completion time"]}', NULL, 'identify the critical path / critical path method / on the critical path', '[{"en":"The delay in testing was on the critical path and delayed the launch.","zh-TW":"測試延遲在關鍵路徑上，延誤了發布。"},{"en":"Project managers use the critical path to prioritize resources.","zh-TW":"項目經理使用關鍵路徑來優先分配資源。"}]', '{"adjective":"critical-path"}', NULL, 5, 1677, NULL),
(1678, 'critical thinking', '/ˈkrɪtɪkəl ˈθɪŋkɪŋ/', 'noun', '{"zh-TW":["批判性思考"],"en":["the objective analysis and evaluation of an issue to form a judgment"]}', NULL, 'critical thinking skills / apply critical thinking / develop critical thinking', '[{"en":"Critical thinking helps managers evaluate options before deciding.","zh-TW":"批判性思考幫助管理者在決策前評估選項。"},{"en":"Business education emphasizes the development of critical thinking.","zh-TW":"商業教育強調批判性思考的培養。"}]', '{"adjective":"critical","verb":"think critically"}', NULL, 5, 1678, NULL),
(1679, 'CRM', '/ˌsiː ɑːr ˈem/', 'noun', '{"zh-TW":["客戶關係管理"],"en":["customer relationship management; software or strategy for managing customer interactions"]}', NULL, 'CRM system / CRM software / implement CRM / update the CRM', '[{"en":"The CRM system tracks all customer communications in one place.","zh-TW":"CRM系統將所有客戶通信集中在一個地方追蹤。"},{"en":"Sales reps must log every call in the CRM.","zh-TW":"銷售代表必須在CRM中記錄每一次通話。"}]', '{"full form":"customer relationship management"}', NULL, 1, 1679, NULL),
(1680, 'crop', '/krɒp/', 'noun', '{"zh-TW":["作物；莊稼"],"en":["plants grown for food"]}', NULL, 'crop rotation / cash crop', '[{"en":"The drought destroyed the crops.","zh-TW":"乾旱摧毀了農作物。"},{"en":"Rice is the main crop here.","zh-TW":"稻米是這裡的主要作物。"}]', NULL, NULL, 1, 1680, NULL),
(1681, 'cross', '/krɒs/', 'verb', '{"zh-TW":["【主要意義-名詞/動詞】十字形；穿越","【次要意義-形容詞】生氣的；易怒的；惱火的"],"en":["[primary] a shape like + or x; to go across","[secondary - adjective] annoyed or angry"]}', NULL, 'cross with someone / at cross purposes', '[{"en":"The manager was cross with the team for missing the deadline.","zh-TW":"經理對團隊錯過截止日期感到惱火。"},{"en":"She seemed rather cross when her proposal was rejected.","zh-TW":"當她的提案被拒絕時，她顯得相當生氣。"},{"en":"They were talking at cross purposes during negotiation.","zh-TW":"他們在談判中各說各話，目的不同。"}]', '{"adverb":"crossly","noun":"crossness"}', 'cross 作形容詞意為「生氣的/惱火的」，是英式英語常見用法，TOEIC 閱讀中出現時容易被誤解為動詞「穿越」，at cross purposes（目的相左）是高階詞彙。', 2, 1681, NULL),
(1682, 'cross-border', '/ˈkrɒs ˌbɔːrdər/', 'adjective', '{"zh-TW":["跨境的；跨國的"],"en":["involving movement or activity across international borders"]}', NULL, 'cross-border transaction / cross-border merger / cross-border e-commerce', '[{"en":"Cross-border transactions require compliance with multiple regulatory regimes.","zh-TW":"跨境交易需要遵守多個監管制度。"},{"en":"Cross-border e-commerce is growing rapidly in emerging markets.","zh-TW":"跨境電子商務在新興市場快速增長。"}]', NULL, NULL, 4, 1682, NULL),
