(1684, 'cross-country', '/''krɒs ˌkʌntri/', 'adjective', '{"zh-TW":["越野的；跨越大地的"],"en":["across fields or countryside, as opposed to along roads or tracks"]}', NULL, 'cross-country running / cross-country skiing / cross-country race', '[{"en":"She won the national cross-country running championship for the second year in a row.","zh-TW":"她連續第二年贏得了全國越野跑錦標賽。"},{"en":"Cross-country skiing is a popular winter sport in Scandinavian countries.","zh-TW":"越野滑雪是斯堪地那維亞國家流行的冬季運動。"}]', NULL, NULL, 5, 1684, NULL),
(1685, 'cross-cultural', '/''krɒs ˌkʌltʃərəl/', 'adjective', '{"zh-TW":["跨文化的；不同文化之間的"],"en":["relating to or involving people from different cultures"]}', NULL, 'cross-cultural communication / cross-cultural team / cross-cultural understanding', '[{"en":"Managing a cross-cultural team requires sensitivity and flexibility.","zh-TW":"管理跨文化團隊需要敏感性和靈活性。"},{"en":"Cross-cultural training helps employees work effectively with international colleagues.","zh-TW":"跨文化培訓幫助員工有效地與國際同事合作。"}]', NULL, NULL, 5, 1685, NULL),
(1686, 'cross-cultural communication', '/''krɒs ˌkʌltʃərəl kəˌmjuːnɪˌkeɪʃən/', 'noun', '{"zh-TW":["跨文化溝通"],"en":["the practice of exchanging information and understanding between people from different cultural backgrounds"]}', NULL, 'improve cross-cultural communication / cross-cultural communication skill / challenge of cross-cultural communication', '[{"en":"Effective cross-cultural communication is essential for multinational business success.","zh-TW":"有效的跨文化溝通對跨國業務的成功至關重要。"},{"en":"Training in cross-cultural communication helps employees avoid misunderstandings with international colleagues.","zh-TW":"跨文化溝通培訓幫助員工避免與國際同事產生誤解。"}]', '{"adjective":"cross-cultural"}', NULL, 5, 1686, NULL),
(1687, 'cross-cultural sensitivity', '/''krɒs ˌkʌltʃərəl ˌsensɪˈtɪvɪti/', 'noun', '{"zh-TW":["跨文化敏感性；文化敏感度"],"en":["awareness and respect for the differences between cultures in communication and behavior"]}', NULL, 'develop cross-cultural sensitivity / demonstrate cross-cultural sensitivity', '[{"en":"Cross-cultural sensitivity is an essential quality for managers of international teams.","zh-TW":"跨文化敏感性是國際團隊管理者的基本素質。"},{"en":"Developing cross-cultural sensitivity reduces misunderstandings in global workplaces.","zh-TW":"發展跨文化敏感性可以減少全球職場中的誤解。"}]', NULL, NULL, 5, 1687, NULL),
(1688, 'cross-cultural training', '/''krɒs ˌkʌltʃərəl ˌtreɪnɪŋ/', 'noun', '{"zh-TW":["跨文化培訓"],"en":["training that prepares people to work effectively with people from different cultural backgrounds"]}', NULL, 'attend cross-cultural training / benefit of cross-cultural training', '[{"en":"Cross-cultural training reduces misunderstandings in international business settings.","zh-TW":"跨文化培訓減少了國際商業環境中的誤解。"},{"en":"Companies with global operations invest heavily in cross-cultural training for their staff.","zh-TW":"有全球業務的公司大量投資於員工的跨文化培訓。"}]', NULL, NULL, 5, 1688, NULL),
(1689, 'cross-department', '/''krɒs dɪˌpɑːrtmənt/', 'adjective', '{"zh-TW":["跨部門的"],"en":["involving or relating to more than one department within an organization"]}', NULL, 'cross-department collaboration / cross-department project / cross-department communication', '[{"en":"The initiative required strong cross-department collaboration to succeed.","zh-TW":"這項舉措需要強大的跨部門合作才能成功。"},{"en":"A cross-department team was formed to tackle the company-wide efficiency problem.","zh-TW":"成立了一個跨部門團隊，以應對公司範圍內的效率問題。"}]', '{"noun":"department"}', NULL, 5, 1689, NULL),
(1690, 'cross-docking', '/''krɒs ˌdɒkɪŋ/', 'noun', '{"zh-TW":["越庫作業；直接換裝"],"en":["a logistics practice where products are transferred directly from incoming to outgoing transport without being stored"]}', NULL, 'implement cross-docking / cross-docking facility / benefit of cross-docking', '[{"en":"Cross-docking eliminates the need for storage and speeds up delivery.","zh-TW":"越庫作業消除了存儲的需求，加快了交付速度。"},{"en":"Large retailers use cross-docking to maintain a lean supply chain.","zh-TW":"大型零售商使用越庫作業來維持精簡的供應鏈。"}]', NULL, NULL, 5, 1690, NULL),
(1691, 'cross-examination', '/krɒs ɪɡˌzæmɪˈneɪʃən/', 'noun', '{"zh-TW":["交叉詰問；反詰問"],"en":["the questioning of a witness by the opposing party in a trial"]}', NULL, 'conduct cross-examination / withstand cross-examination / cross-examination of witnesses', '[{"en":"The attorney''s skillful cross-examination revealed inconsistencies in the testimony.","zh-TW":"律師嫻熟的交叉詰問揭示了證詞中的矛盾。"},{"en":"Cross-examination is a fundamental right in adversarial legal systems.","zh-TW":"在對抗制法律體系中，交叉詰問是基本權利。"}]', '{"verb":"cross-examine"}', NULL, 5, 1691, NULL),
(1692, 'cross-functional', '/krɒs ˈfʌŋkʃənəl/', 'adjective', '{"zh-TW":["跨部門的；跨功能的"],"en":["involving people from different areas of an organization"]}', NULL, 'cross-functional team / cross-functional collaboration', '[{"en":"A cross-functional team was formed to solve the problem.","zh-TW":"成立了一個跨部門團隊來解決這個問題。"},{"en":"Cross-functional collaboration improves innovation and communication.","zh-TW":"跨部門合作促進了創新和溝通。"}]', NULL, NULL, 5, 1692, NULL),
(1693, 'cross-functional collaboration', '/krɒs ˈfʌŋkʃənəl kəˌlæbəˌreɪʃən/', 'noun', '{"zh-TW":["跨職能合作"],"en":["working together with people from different functional areas or departments to achieve a shared goal"]}', NULL, 'promote cross-functional collaboration / benefit of cross-functional collaboration / enable cross-functional collaboration', '[{"en":"Cross-functional collaboration between engineering and marketing led to a breakthrough product design.","zh-TW":"工程部門和市場部門之間的跨職能合作帶來了突破性的產品設計。"},{"en":"The company restructured to encourage more cross-functional collaboration across business units.","zh-TW":"公司重組，以鼓勵業務單位之間更多的跨職能合作。"}]', '{"adjective":"cross-functional"}', NULL, 5, 1693, NULL),
(1694, 'cross-functional team', '/krɒs ˈfʌŋkʃənəl tiːm/', 'noun', '{"zh-TW":["跨職能團隊"],"en":["a group of people from different departments working together"]}', NULL, 'cross-functional team collaboration / lead a cross-functional team', '[{"en":"A cross-functional team was formed to launch the product.","zh-TW":"成立了一個跨職能團隊來推出該產品。"},{"en":"Cross-functional teams improve communication across departments.","zh-TW":"跨職能團隊改善了各部門之間的溝通。"}]', '{"adjective":"cross-functional"}', NULL, 5, 1694, NULL),
(1695, 'cross-sell', '/krɒs sel/', 'verb', '{"zh-TW":["交叉銷售"],"en":["to persuade an existing customer to buy additional related products"]}', NULL, 'cross-sell products / cross-sell opportunity / cross-selling strategy', '[{"en":"Bank staff are trained to cross-sell insurance and investment products.","zh-TW":"銀行員工接受培訓，向客戶交叉銷售保險和投資產品。"},{"en":"Cross-selling increased average revenue per customer by 25%.","zh-TW":"交叉銷售使每位客戶的平均收入增加了25%。"}]', '{"noun":"cross-selling","adjective":"cross-sell"}', NULL, 4, 1695, NULL),
(1696, 'cross-selling', '/ˈkrɒsselɪŋ/', 'noun', '{"zh-TW":["交叉銷售"],"en":["encouraging customers to buy complementary products or services"]}', NULL, 'cross-selling opportunity / cross-selling strategy / effective cross-selling', '[{"en":"Cross-selling insurance products alongside mortgages boosts revenue.","zh-TW":"在抵押貸款旁邊交叉銷售保險產品可提升收入。"},{"en":"The CRM system helps identify cross-selling opportunities.","zh-TW":"CRM系統幫助識別交叉銷售機會。"}]', '{"verb":"cross-sell"}', NULL, 5, 1696, NULL),
(1697, 'cross-subsidization', '/ˈkrɒs ˌsʌbsɪdaɪˈzeɪʃən/', 'noun', '{"zh-TW":["交叉補貼"],"en":["the practice of using profits from one part of a business to offset losses in another"]}', NULL, 'internal cross-subsidization / cross-subsidization between divisions / eliminate cross-subsidization', '[{"en":"Cross-subsidization allows profitable routes to fund less profitable but socially essential services.","zh-TW":"交叉補貼允許盈利路線資助盈利能力較低但對社會至關重要的服務。"},{"en":"Regulators investigated whether cross-subsidization between divisions violated competition law.","zh-TW":"監管機構調查了部門之間的交叉補貼是否違反了競爭法。"}]', NULL, NULL, 5, 1697, NULL),
(1698, 'cross-training', '/''krɒs ˌtreɪnɪŋ/', 'noun', '{"zh-TW":["交叉訓練；多項目訓練"],"en":["training in more than one sport or physical activity to improve overall fitness"]}', NULL, 'benefit from cross-training / add cross-training / cross-training routine', '[{"en":"Cross-training helps prevent overuse injuries by varying the types of exercise.","zh-TW":"交叉訓練通過變化運動類型來幫助防止過度使用傷害。"},{"en":"Swimmers often use cross-training such as yoga and strength work to complement their pool training.","zh-TW":"游泳運動員通常使用瑜伽和力量訓練等交叉訓練來補充池中訓練。"}]', NULL, NULL, 5, 1698, NULL),
(1699, 'crowd', '/kraʊd/', 'noun', '{"zh-TW":["人群"],"en":["a large number of people gathered together"]}', NULL, 'crowd of people / stand out from the crowd', '[{"en":"A large crowd gathered outside.","zh-TW":"一大群人聚集在外面。"},{"en":"She stood out from the crowd.","zh-TW":"她在人群中脫穎而出。"}]', '{"adjective":"crowded"}', NULL, 2, 1699, NULL);